    "google",
    "api",
    "google",
    "docs",
    "html",
    "markdown"
  ],
  "author": "Filipe Deschamps",
  "license": "MIT",
  "bugs": {
    "url": "https://github.com/filipedeschamps/parse-google-docs-json/issues"
  },
  "homepage": "https://github.com/filipedeschamps/parse-google-docs-json#readme",
  "typings": "index.d.ts",
  "dependencies": {
    "googleapis": "148.0.0",
    "json2md": "1.7.1",
    "lodash.get": "4.4.2",
    "lodash.last": "3.0.0",
    "lodash.repeat": "4.1.0",
    "yamljs": "0.3.0"
  }
}

